//! Console keyboard layouts.
//!
//! The system's default layout and the layouts a user may choose come from
//! `/etc/resilience/system.toml` (`[keyboard]`, generated by Nix from
//! `resilience.keyboard.*`, every name checked at build time). A user's
//! choice is saved in their settings and applied by the privileged helper
//! (`resilience-admin set-keymap`, ADR 0017): the kernel lets only
//! CAP_SYS_TTY_CONFIG change the console keymap, because a keymap can also
//! bind whole strings to keys. The helper accepts only the names listed in
//! its root-owned configuration and runs `loadkeys` with fixed arguments.
//!
//! The Linux console has one keymap for all its consoles: a layout chosen
//! in one session applies to every console until it is changed again. The
//! system puts its default layout back before every login prompt, so the
//! next person never types a password with someone else's layout.

use serde::Deserialize;

/// A layout the user may choose.
#[derive(Debug, Clone, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct Layout {
    /// kbd keymap name, such as `fr` or `de-latin1`.
    pub id: String,
    /// Shown to people, such as "French (AZERTY)".
    pub label: String,
}

#[derive(Debug, Clone, Deserialize, PartialEq, Eq)]
#[serde(default, deny_unknown_fields)]
pub struct KeyboardConfig {
    /// The system's layout: login prompts and every console at boot.
    pub default: String,
    /// The layouts offered in the interface (the default among them).
    pub layouts: Vec<Layout>,
    /// Installed systems (ADR 0022): a root-owned file holding the layout
    /// chosen when installing, which then replaces `default`.
    pub state_file: Option<std::path::PathBuf>,
}

impl Default for KeyboardConfig {
    fn default() -> Self {
        KeyboardConfig {
            default: "us".into(),
            layouts: vec![Layout {
                id: "us".into(),
                label: "English (US, QWERTY)".into(),
            }],
            state_file: None,
        }
    }
}

/// The XKB layout and variant (Wayland, ADR 0026) matching a kbd keymap
/// name, for the layouts Resilience offers and common others. `None` for
/// names we do not know: the caller then keeps the US layout.
pub fn xkb_for(id: &str) -> Option<(&'static str, &'static str)> {
    Some(match id {
        "us" => ("us", ""),
        "uk" => ("gb", ""),
        "fr" | "fr-latin1" | "fr-latin9" => ("fr", ""),
        "fr-bepo" => ("fr", "bepo"),
        "be-latin1" => ("be", ""),
        "fr_CH" | "fr_CH-latin1" => ("ch", "fr"),
        "de" | "de-latin1" => ("de", ""),
        "de-latin1-nodeadkeys" => ("de", "nodeadkeys"),
        "de_CH-latin1" | "sg" | "sg-latin1" => ("ch", ""),
        "es" => ("es", ""),
        "it" => ("it", ""),
        "pt-latin1" => ("pt", ""),
        "br-abnt2" => ("br", ""),
        "nl" => ("nl", ""),
        "dvorak" => ("us", "dvorak"),
        "pl" | "pl2" => ("pl", ""),
        "ru" => ("ru", ""),
        "se-lat6" | "se-latin1" => ("se", ""),
        "no-latin1" | "no" => ("no", ""),
        "dk-latin1" | "dk" => ("dk", ""),
        "fi" => ("fi", ""),
        _ => return None,
    })
}

/// A keymap name we are willing to pass to `loadkeys`: 1 to 40 ASCII
/// letters, digits, `-` and `_`, not starting with `-`.
pub fn is_valid_id(id: &str) -> bool {
    !id.is_empty()
        && id.len() <= 40
        && !id.starts_with('-')
        && id
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'-' || b == b'_')
}

impl KeyboardConfig {
    /// Apply the content of the state file (`KEYMAP=<id>`, the syntax of
    /// vconsole.conf, which the initrd reads as an environment file): the
    /// system layout becomes that one if it is offered and valid. Returns
    /// whether it did.
    pub fn apply_state(&mut self, text: &str) -> bool {
        let Some(id) = parse_state(text) else {
            return false;
        };
        if self.find(id).is_some() {
            self.default = id.to_string();
            true
        } else {
            false
        }
    }

    /// Read the state file, if this system has one (missing or unusable:
    /// the built-in layout stays, as at the login prompts).
    pub fn read_state(&mut self) {
        if let Some(text) = self
            .state_file
            .as_ref()
            .and_then(|p| std::fs::read_to_string(p).ok())
        {
            self.apply_state(&text);
        }
    }

    /// The listed layout with this name.
    pub fn find(&self, id: &str) -> Option<&Layout> {
        self.layouts.iter().find(|l| l.id == id)
    }

    /// The layout that applies for a saved choice: the choice if it is
    /// still offered, otherwise the system default.
    pub fn effective<'a>(&'a self, saved: Option<&'a str>) -> &'a str {
        match saved {
            Some(id) if self.find(id).is_some() && is_valid_id(id) => id,
            _ => &self.default,
        }
    }

    /// The label of a layout, or its name when it is not listed.
    pub fn label<'a>(&'a self, id: &'a str) -> &'a str {
        self.find(id).map_or(id, |l| l.label.as_str())
    }
}

/// The layout named by a state file: exactly one line `KEYMAP=<valid id>`.
pub fn parse_state(text: &str) -> Option<&str> {
    let line = text.strip_suffix('\n').unwrap_or(text);
    let id = line.strip_prefix("KEYMAP=")?;
    is_valid_id(id).then_some(id)
}

/// The content of a state file naming `id`.
pub fn state_text(id: &str) -> String {
    format!("KEYMAP={id}\n")
}

/// `loadkeys` arguments for a valid keymap name; `None` otherwise. Which
/// names are allowed is decided by the caller (the helper's list).
pub fn loadkeys_argv(loadkeys: &str, id: &str) -> Option<Vec<String>> {
    is_valid_id(id).then(|| {
        vec![
            loadkeys.to_string(),
            "-q".to_string(),
            "--".to_string(),
            id.to_string(),
        ]
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn cfg() -> KeyboardConfig {
        KeyboardConfig {
            default: "us".into(),
            layouts: vec![
                Layout {
                    id: "us".into(),
                    label: "English (US, QWERTY)".into(),
                },
                Layout {
                    id: "fr".into(),
                    label: "French (AZERTY)".into(),
                },
                Layout {
                    id: "-x".into(),
                    label: "listed but invalid".into(),
                },
            ],
            state_file: None,
        }
    }

    #[test]
    fn state_replaces_the_default_only_with_an_offered_layout() {
        let mut c = cfg();
        assert!(c.apply_state(&state_text("fr")));
        assert_eq!(c.default, "fr");
        for bad in [
            "KEYMAP=de",
            "KEYMAP=-x",
            "",
            "fr",
            "KEYMAP=fr us",
            "KEYMAP=../fr",
            "KEYMAP=fr\nKEYMAP=us\n",
            " KEYMAP=fr",
        ] {
            let mut c = cfg();
            assert!(!c.apply_state(bad), "{bad:?}");
            assert_eq!(c.default, "us");
        }
    }

    #[test]
    fn ids_are_checked() {
        for ok in ["us", "fr", "de-latin1", "fr_CH", "be-latin1", "a"] {
            assert!(is_valid_id(ok), "{ok}");
        }
        let long = "a".repeat(41);
        for bad in [
            "",
            "-q",
            "fr us",
            "../fr",
            "fr;rm",
            "é",
            "fr\n",
            long.as_str(),
        ] {
            assert!(!is_valid_id(bad), "{bad:?}");
        }
    }

    #[test]
    fn only_valid_names_reach_loadkeys() {
        assert_eq!(
            loadkeys_argv("/bin/loadkeys", "fr"),
            Some(vec![
                "/bin/loadkeys".to_string(),
                "-q".into(),
                "--".into(),
                "fr".into()
            ])
        );
        assert_eq!(loadkeys_argv("/bin/loadkeys", "-x"), None);
        assert_eq!(loadkeys_argv("/bin/loadkeys", "fr us"), None);
    }

    #[test]
    fn saved_choice_falls_back_to_the_default() {
        let c = cfg();
        assert_eq!(c.effective(Some("fr")), "fr");
        assert_eq!(c.effective(Some("de")), "us");
        assert_eq!(c.effective(Some("-x")), "us");
        assert_eq!(c.effective(None), "us");
        assert_eq!(c.label("fr"), "French (AZERTY)");
        assert_eq!(c.label("xx"), "xx");
    }

    #[test]
    fn parsed_from_the_system_file() {
        let c: KeyboardConfig = toml::from_str(
            "default = \"fr\"\n[[layouts]]\nid = \"fr\"\nlabel = \"French (AZERTY)\"\n",
        )
        .expect("parse");
        assert_eq!(c.default, "fr");
        assert_eq!(c.layouts.len(), 1);
        assert!(toml::from_str::<KeyboardConfig>("surprise = 1").is_err());
        assert_eq!(
            toml::from_str::<KeyboardConfig>("").expect("empty"),
            KeyboardConfig::default()
        );
    }

    #[test]
    fn xkb_names_for_offered_layouts() {
        for id in [
            "us",
            "uk",
            "fr",
            "fr-bepo",
            "be-latin1",
            "fr_CH",
            "de-latin1",
            "de_CH-latin1",
            "es",
            "it",
            "pt-latin1",
            "nl",
            "dvorak",
        ] {
            assert!(xkb_for(id).is_some(), "{id}");
        }
        assert_eq!(xkb_for("uk"), Some(("gb", "")));
        assert_eq!(xkb_for("fr-bepo"), Some(("fr", "bepo")));
        assert_eq!(xkb_for("nope"), None);
    }
}
